(3722156, 515152, 24974, '<td valign="top">I bet the parents LOVED this shot! Awesome candid.</td>', 'I bet the parents LOVED this shot! Awesome candid.', '2007-06-01 02:29:27.000000', NULL, 1),
(3722157, 524116, 22970, '<td valign="top">Nice texture and detail. Subject really stands out even though not that exciting. Still an above average photograph.</td>', 'Nice texture and detail. Subject really stands out even though not that exciting. Still an above average photograph.', '2007-06-01 02:29:30.000000', NULL, 1),
