(3722289, 510738, 76454, '<td valign="top">You have probably heard this already, but... The Highly compressed, JPEG, Pixely look, does not add to the image.</td>', 'You have probably heard this already, but... The Highly compressed, JPEG, Pixely look, does not add to the image.', '2007-06-01 03:05:09.000000', NULL, 1),
(3722300, 513208, 19831, '<td valign="top">Wowsers! An incredible capture, and executed very well too. A very cool shot to have!</td>', 'Wowsers! An incredible capture, and executed very well too. A very cool shot to have!', '2007-06-01 03:10:33.000000', NULL, 1),
