(3727677, 524949, 39531, '<td valign="top">Great sharpness I would have liked a bit more saturation</td>', 'Great sharpness I would have liked a bit more saturation', '2007-06-02 03:25:44.000000', NULL, 1),
(3727682, 516534, 39531, '<td valign="top">I am not usually a dog and cat picture person but, this on is a exception. You really did a great job of catching a mood here and the technical aspects are excellent.</td>', 'I am not usually a dog and cat picture person but, this on is a exception. You really did a great job of catching a mood here and the technical aspects are excellent.', '2007-06-02 03:26:56.000000', NULL, 1),
