(3733279, 521448, 43774, '<td valign="top">Amazing composition, the tree reaching out for the water drops, perfect!</td>', 'Amazing composition, the tree reaching out for the water drops, perfect!', '2007-06-03 19:14:42.000000', NULL, 1),
(3733283, 525040, 43774, '<td valign="top">Beautiful scene, I love that you included the bench and not just the view from the bench.</td>', 'Beautiful scene, I love that you included the bench and not just the view from the bench.', '2007-06-03 19:15:08.000000', NULL, 1),
(3733284, 525367, 43774, '<td valign="top">This is so soft and subtle, the muted colours are very pleasing.</td>', 'This is so soft and subtle, the muted colours are very pleasing.', '2007-06-03 19:15:30.000000', NULL, 1),
