(3733299, 522651, 43774, '<td valign="top">Wonderful composition, the angle gives us a sense of how high the falls are.</td>', 'Wonderful composition, the angle gives us a sense of how high the falls are.', '2007-06-03 19:17:26.000000', NULL, 1),
(3733300, 517887, 43774, '<td valign="top">Very clear, great DOF</td>', 'Very clear, great DOF', '2007-06-03 19:17:43.000000', NULL, 1),
