(3745807, 524129, 35602, '<td valign="top">Really nice lighting.  A classic image which is timeless.  8</td>', 'Really nice lighting.  A classic image which is timeless.  8', '2007-06-06 08:13:47.000000', NULL, 1),
(3745822, 523688, 35602, '<td valign="top">Just a bit too much motion.  Need something to focus the viewer.</td>', 'Just a bit too much motion.  Need something to focus the viewer.', '2007-06-06 08:17:35.000000', NULL, 1),
(3745828, 517617, 35602, '<td valign="top">Different processing.</td>', 'Different processing.', '2007-06-06 08:20:19.000000', NULL, 1),
