INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3750238, 525425, 19708, '<td valign="top">I like the scene, composition and the b&amp;w conversion, but the the buildings have an odd curve/ tilt makes this a bit odd to look at.</td>', 'I like the scene, composition and the b&w conversion, but the the buildings have an odd curve/ tilt makes this a bit odd to look at.', '2007-06-07 02:16:19.000000', NULL, 1),
(3750239, 524724, 79577, '<td valign="top">This is an outstanding picture. Marvelous composition and great lighting.</td>', 'This is an outstanding picture. Marvelous composition and great lighting.', '2007-06-07 02:16:30.000000', NULL, 1),
(3750242, 524556, 19708, '<td valign="top">Very good detail in your macro. A touch on the harsh / higher than needed contrast side though.</td>', 'Very good detail in your macro. A touch on the harsh / higher than needed contrast side though.', '2007-06-07 02:17:06.000000', NULL, 1),
(3750243, 523745, 19708, '<td valign="top">Nice infrared shot and composition. Odd to have a 20mph speed limit though....</td>', 'Nice infrared shot and composition. Odd to have a 20mph speed limit though....', '2007-06-07 02:17:59.000000', NULL, 1),
(3750245, 514212, 19708, '<td valign="top">I honestly do not know why you have entered this. I don''t understand it, can''t figure out what it is, and is so soft that no real focal point exists.</td>', 'I honestly do not know why you have entered this. I don''t understand it, can''t figure out what it is, and is so soft that no real focal point exists.', '2007-06-07 02:19:25.000000', NULL, 1),
(3750249, 524584, 19708, '<td valign="top">Great shot, though I wish some local sharpening had been done on the bee to bring out some more detail.</td>', 'Great shot, though I wish some local sharpening had been done on the bee to bring out some more detail.', '2007-06-07 02:20:42.000000', NULL, 1),
(3750251, 522479, 19708, '<td valign="top">Funny the scenes that develop in front of us (or behind us). Nice levels and tones on this.</td>', 'Funny the scenes that develop in front of us (or behind us). Nice levels and tones on this.', '2007-06-07 02:21:39.000000', NULL, 1),
(3750252, 520941, 19708, '<td valign="top">Very nicely done silhouette.</td>', 'Very nicely done silhouette.', '2007-06-07 02:22:04.000000', NULL, 1),
(3750253, 507455, 19708, '<td valign="top">I''d love to have been behind your eyes when you took this to understand how you saw this and what triggered you to take the shot. This is meant as a compliment by the way, as this is superb.</td>', 'I''d love to have been behind your eyes when you took this to understand how you saw this and what triggered you to take the shot. This is meant as a compliment by the way, as this is superb.', '2007-06-07 02:23:46.000000', NULL, 1),
(3750254, 524254, 19708, '<td valign="top">Be careful of composing / cropping with your main focal point so dead-center.</td>', 'Be careful of composing / cropping with your main focal point so dead-center.', '2007-06-07 02:24:28.000000', NULL, 1),
