(3752086, 524116, 67152, '<td valign="top">Wonderful tones and colors - fantastic image of something so small and common but done in such an uncommon way.</td>', 'Wonderful tones and colors - fantastic image of something so small and common but done in such an uncommon way.', '2007-06-07 15:10:57.000000', NULL, 1),
(3752089, 510743, 67152, '<td valign="top">You win the prize for making something necessary but ugly into something beautiful.  Love the gradient of blue to red and the starbursts on the lights.</td>', 'You win the prize for making something necessary but ugly into something beautiful.  Love the gradient of blue to red and the starbursts on the lights.', '2007-06-07 15:11:06.000000', NULL, 1),
(3752091, 521077, 67152, '<td valign="top">Stunning image - great detail in the sea - very solid composition and color choices</td>', 'Stunning image - great detail in the sea - very solid composition and color choices', '2007-06-07 15:11:08.000000', NULL, 1),
