(3752101, 525037, 66833, '<td valign="top">Nice &amp; Natural. Love the green tones</td>', 'Nice & Natural. Love the green tones', '2007-06-07 15:12:41.000000', NULL, 1),
(3752103, 508959, 48717, '<td valign="top">Great processing and composition!</td>', 'Great processing and composition!', '2007-06-07 15:13:02.000000', NULL, 1),
