INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3757309, 509860, 61651, '<td valign="top">Great wide sky and overall starkness, although you lose me a bit with that center cloud - on my monitor at least, it looks a bit posterized.</td>', 'Great wide sky and overall starkness, although you lose me a bit with that center cloud - on my monitor at least, it looks a bit posterized.', '2007-06-08 13:32:57.000000', NULL, 0),
(3757314, 525395, 65603, '<td valign="top">Thank you Everyone!!!! I think this was one of the best round of helpful comments ever. I personally like the plain but beauty of the distant mountain.</td>', 'Thank you Everyone!!!! I think this was one of the best round of helpful comments ever. I personally like the plain but beauty of the distant mountain.', '2007-06-08 13:35:35.000000', NULL, 0),
(3757318, 525199, 61651, '<td valign="top">Great wide un-mown foreground to contrast with the further field.  Invincible summer...the wild and rampant summer growth is advancing on the background scene, like an army.  Am I reading too much into this? :)</td>', 'Great wide un-mown foreground to contrast with the further field.  Invincible summer...the wild and rampant summer growth is advancing on the background scene, like an army.  Am I reading too much into this? :)', '2007-06-08 13:37:11.000000', NULL, 0),
